int format_metric_point(char* metric_name, char** label_keys, char** label_values, int label_count, char* metric_output) {
    if (!metric_name || !label_keys || !label_values || !metric_output || label_count < 0) {
        return -1;
    }

    // Initialize the output buffer
    metric_output[0] = '\0';

    // Copy the metric name to the output
    int offset = snprintf(metric_output, 1024, "%s", metric_name);
    if (offset < 0 || offset >= 1024) {
        return -1;
    }

    // If there are labels, add them in the format {key1="value1",key2="value2",...}
    if (label_count > 0) {
        offset += snprintf(metric_output + offset, 1024 - offset, "{");
        if (offset >= 1024) {
            return -1;
        }

        for (int i = 0; i < label_count; i++) {
            if (!label_keys[i] || !label_values[i]) {
                return -1;
            }

            int written = snprintf(metric_output + offset, 1024 - offset, "%s=\"%s\"", label_keys[i], label_values[i]);
            if (written < 0 || offset + written >= 1024) {
                return -1;
            }
            offset += written;

            // Add comma separator if not the last label
            if (i < label_count - 1) {
                if (offset + 1 >= 1024) {
                    return -1;
                }
                metric_output[offset++] = ',';
                metric_output[offset] = '\0';
            }
        }

        // Close the label block
        offset += snprintf(metric_output + offset, 1024 - offset, "}");
        if (offset >= 1024) {
            return -1;
        }
    }

    // Add a timestamp to the metric output (optional, for demonstration)
    time_t current_time = time(NULL);
    offset += snprintf(metric_output + offset, 1024 - offset, " %ld", current_time);
    if (offset >= 1024) {
        return -1;
    }

    return 0; // Success
}
